mkdir -p "$FOAM_RUN"
cp -r "$FOAM_TUTORIALS/compressible/rhoSimpleFoam/squareBendLiqNoNewtonian" "$FOAM_RUN/squareBendLiqNoNewtonian-reference"
cd "$FOAM_RUN/squareBendLiqNoNewtonian-reference"
./Allrun
